-- Der Hinweis vor dem Speichern sagt die Wahrheit (#417), und die wartende
-- Bestätigung steht in den offenen Punkten (#418).
--
-- help_termine_11 bekommt einen Satz dazu. Der früheste Seed gewinnt, also
-- muss der alte Wortlaut einmal weg - mit Marke, damit das einmal geschieht.
SET NAMES utf8mb4;

DELETE FROM translations WHERE tkey = 'help_termine_11'
  AND (SELECT COUNT(*) FROM settings WHERE `key` = 'hilfe_termine_11_418') = 0;
  ON DUPLICATE KEY UPDATE value = value;

ON DUPLICATE KEY UPDATE value = value;
